/**
 * Activity Tracking Hook
 * Provides comprehensive activity logging
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { API_ENDPOINTS } from '../utils/config';
import toast from 'react-hot-toast';

interface ActivityData {
  entity_type: string;
  entity_id: string;
  action_type: string;
  description: string;
  metadata?: Record<string, any>;
  project_id?: string;
  task_id?: string;
  tab_name?: string;
}

interface ActivityLog extends ActivityData {
  session_id?: string;
  user_agent?: string;
  ip_address?: string;
}

export const useActivityTracking = (projectId?: string) => {
  const { tokens, user } = useAuth();
  const [isTrackingEnabled, setIsTrackingEnabled] = useState(true);
  const sessionId = useRef<string>(generateSessionId());

  // No geolocation initialization needed

  // Geolocation functionality removed

  /**
   * Log an activity
   */
  const logActivity = useCallback(async (activityData: ActivityData): Promise<boolean> => {
    if (!tokens?.access_token || !isTrackingEnabled) {
      return false;
    }

    try {
      const activityLog: ActivityLog = {
        ...activityData,
        // Add session and environment data
        session_id: sessionId.current,
        user_agent: navigator.userAgent,
        project_id: activityData.project_id || projectId,
      };

      const response = await fetch(API_ENDPOINTS.activities.create, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${tokens.access_token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(activityLog),
      });

      if (!response.ok) {
        throw new Error(`Failed to log activity: ${response.status}`);
      }

      console.log('Activity logged:', activityLog.description);
      return true;
    } catch (error) {
      console.error('Error logging activity:', error);
      return false;
    }
  }, [tokens, isTrackingEnabled, projectId]);

  /**
   * Log project tab navigation
   */
  const logTabNavigation = useCallback(async (tabName: string, projectId: string) => {
    return await logActivity({
      entity_type: 'project',
      entity_id: projectId,
      action_type: 'tab_viewed',
      description: `Viewed ${tabName} tab`,
      metadata: { 
        previous_tab: document.referrer ? 'previous_tab' : 'direct',
        tab_switch_timestamp: new Date().toISOString()
      },
      project_id: projectId,
      tab_name: tabName
    });
  }, [logActivity]);

  /**
   * Log project actions (create, update, delete, etc.)
   */
  const logProjectAction = useCallback(async (
    action: string, 
    projectId: string, 
    description: string, 
    metadata?: Record<string, any>
  ) => {
    return await logActivity({
      entity_type: 'project',
      entity_id: projectId,
      action_type: action,
      description,
      metadata,
      project_id: projectId
    });
  }, [logActivity]);

  /**
   * Log task actions
   */
  const logTaskAction = useCallback(async (
    action: string,
    taskId: string,
    projectId: string,
    description: string,
    metadata?: Record<string, any>
  ) => {
    return await logActivity({
      entity_type: 'task',
      entity_id: taskId,
      action_type: action,
      description,
      metadata,
      project_id: projectId,
      task_id: taskId
    });
  }, [logActivity]);

  /**
   * Log milestone actions
   */
  const logMilestoneAction = useCallback(async (
    action: string,
    milestoneId: string,
    projectId: string,
    description: string,
    metadata?: Record<string, any>
  ) => {
    return await logActivity({
      entity_type: 'milestone',
      entity_id: milestoneId,
      action_type: action,
      description,
      metadata,
      project_id: projectId
    });
  }, [logActivity]);

  /**
   * Log comment actions
   */
  const logCommentAction = useCallback(async (
    action: string,
    commentId: string,
    entityType: string,
    entityId: string,
    description: string,
    metadata?: Record<string, any>
  ) => {
    return await logActivity({
      entity_type: 'comment',
      entity_id: commentId,
      action_type: action,
      description,
      metadata: {
        ...metadata,
        parent_entity_type: entityType,
        parent_entity_id: entityId
      },
      project_id: projectId
    });
  }, [logActivity, projectId]);

  /**
   * Log file actions
   */
  const logFileAction = useCallback(async (
    action: string,
    fileId: string,
    fileName: string,
    projectId: string,
    description: string,
    metadata?: Record<string, any>
  ) => {
    return await logActivity({
      entity_type: 'file',
      entity_id: fileId,
      action_type: action,
      description,
      metadata: {
        ...metadata,
        file_name: fileName
      },
      project_id: projectId
    });
  }, [logActivity]);

  // Geolocation toggle functionality removed

  /**
   * Toggle activity tracking
   */
  const toggleActivityTracking = useCallback((enabled: boolean) => {
    setIsTrackingEnabled(enabled);
    toast.success(`Activity tracking ${enabled ? 'enabled' : 'disabled'}`);
  }, []);

  return {
    // State
    isTrackingEnabled,
    
    // General activity logging
    logActivity,
    
    // Specific activity logging methods
    logTabNavigation,
    logProjectAction,
    logTaskAction,
    logMilestoneAction,
    logCommentAction,
    logFileAction,
    
    // Settings
    toggleActivityTracking,
  };
};

/**
 * Generate a unique session ID
 */
function generateSessionId(): string {
  return `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
}

export default useActivityTracking;